+@push('scripts')<script>const memberSearch=document.getElementById('memberSearch'),memberResults=document.getElementById('memberResults'),identityAssignment=document.getElementById('identityAssignment'),selectedMember=document.getElementById('selectedMember');let searchTimer;memberSearch.addEventListener('input',()=>{clearTimeout(searchTimer);const query=memberSearch.value.trim();memberResults.innerHTML='';if(query.length<2)return;searchTimer=setTimeout(()=>fetch('{{ route('admin.users.search') }}?q='+encodeURIComponent(query),{headers:{Accept:'application/json'}}).then(response=>response.json()).then(users=>{memberResults.innerHTML=users.map(user=>`<button type="button" class="block w-full border border-silver-800 bg-pitch-950 p-2 text-left text-xs hover:border-white" data-id="${user.id}" data-name="${user.name}" data-citizen="${user.citizen_number||''}">${user.name} // ${user.citizen_number||user.email}</button>`).join('');memberResults.querySelectorAll('button').forEach(button=>button.onclick=()=>{identityAssignment.action='{{ url('/admin/users') }}/'+button.dataset.id+'/identity';selectedMember.textContent='Selected: '+button.dataset.name+' // '+button.dataset.citizen;memberResults.innerHTML='';memberSearch.value=button.dataset.name})}).catch(()=>{memberResults.innerHTML='<p class="text-red-300">Member search unavailable.</p>'})},250)})</script>@endpush
